function CollectionPage({ slug }) {
  useReveal();
  const page = NON_CONSUMER_COLLECTION_SLUGS.has(slug) ? COLLECTION_PAGES['strength-training'] : (COLLECTION_PAGES[slug] || COLLECTION_PAGES['strength-training']);
  const collectionRoute = `/collections/${slug}`;
  const finalizedFaqs = FINALIZED_ROUTE_FAQS[collectionRoute] || finalizeConsumerRouteFaqs({
    route: collectionRoute,
    title: page.title,
    topic: page.eyebrow,
    description: page.intro,
    kind: 'collection',
    faqs: page.faq,
  });
  const articleList = page.articles
    .map((articleSlug) => PUBLIC_ARTICLES.find((article) => article.slug === articleSlug))
    .filter(Boolean);
  const first = articleList[0] || PUBLIC_ARTICLES[0];
  return (
    <>
      <PageHeader eyebrow={page.eyebrow} title={page.title} intro={page.intro} />
      <AlohaDemandBlock route={collectionRoute} />
      <section className="section section--tight">
        <div className="wrap articlewrap">
          <aside className="articlemeta">
            <div className="articlemeta__box">
              <span className="idx">Collection Size</span>
              <b>{articleList.length} guides</b>
            </div>
            <div className="articlemeta__box">
              <span className="idx">Start Here</span>
              <Link href={`/resources/${first.slug}`}>{first.title} →</Link>
            </div>
            <div className="articlemeta__box articlemeta__box--accent">
              <span className="idx">Next Step</span>
              <b>Use the fit check when the problem repeats.</b>
              <Link href="/free/forge-readiness-check">Start free check →</Link>
            </div>
          </aside>
          <article className="articlebody">
            <p className="articlebody__lede">{page.summary}</p>
            {slug === 'supplements' && (
              <section className="articleanswer articleanswer--quiet" data-analytics-source="supplements_commerce_bridge">
                <span className="idx">Current Product Details</span>
                <h2>Compare Titan Forge supplements with the live label in view.</h2>
                <p>This collection owns the education and decision context. Current product labels, prices, availability, and checkout remain on the Shopify storefront so those details come from the catalog rather than duplicated page copy.</p>
                <a className="btn btn--ghost" href="https://shop.titanforgefit.com/collections/supplements" target="_blank" rel="noreferrer" data-analytics-event="shopify_collection_click" data-analytics-source="supplements_commerce_bridge" data-analytics-link-kind="shop" data-product-intent="forge_supplements">View Current Supplements <span className="arr">→</span></a>
              </section>
            )}
            <section className="articleanswer">
              <span className="idx">Short Answer</span>
              <h2>How to use this collection.</h2>
              <p>Read the guide that matches the current problem, then apply the smallest useful decision for a full week before changing the plan again. If the same problem keeps coming back, that is the signal that coaching may be more useful than more information.</p>
            </section>
            <section>
              <h2>Guides in this collection.</h2>
              <div className="arts" style={{ marginTop: 18 }}>
                {articleList.map((article, i) => (
                  <Link href={`/resources/${article.slug}`} className="art" key={article.slug} data-analytics-event="resource_result_click" data-analytics-source={`collection_${slug}`} data-analytics-link-kind="resource">
                    <span className="art__n">{String(i + 1).padStart(2, '0')}</span>
                    <div className="art__main">
                      <h3>{article.title}</h3>
                      <div className="art__meta">{article.cat} · {article.mins} min read · {article.keyword}</div>
                    </div>
                    <span className="art__go">Read →</span>
                  </Link>
                ))}
              </div>
            </section>
            <section className="articlefaq">
              <span className="idx">Collection FAQ</span>
              <h2>Common questions.</h2>
              {finalizedFaqs.map(([q, a]) => (
                <details key={q}>
                  <summary>{q}</summary>
                  <p>{a}</p>
                </details>
              ))}
            </section>
            <div className="articlecta">
              <span className="idx">Use The System</span>
              <h3>Turn the collection into a first step.</h3>
              <p>Use the path finder if you are unsure, the free readiness check if you need a lower-pressure filter, or apply when you know the problem needs feedback.</p>
              <div className="ctaband__cta" style={{ justifyContent: 'flex-start', marginTop: 24 }}>
                <Btn kind="ember" href="/apply" arrow data-analytics-source={`collection_${slug}_cta`} data-analytics-link-kind="apply">Apply For Coaching</Btn>
                <Btn kind="ghost" href="/start" data-analytics-link-kind="selector">Find Your Path</Btn>
              </div>
            </div>
          </article>
        </div>
      </section>
    </>
  );
}

function FaqHubPage() {
  useReveal();
  const faqGroups = FAQ_HUB_GROUPS
    .map((group) => ({ ...group, faqs: group.faqs.filter(isConsumerFaq) }))
    .filter((group) => group.faqs.length);
  const total = faqGroups.reduce((sum, group) => sum + group.faqs.length, 0);
  return (
    <>
      <PageHeader eyebrow="FAQ Hub" title={editableCopyNode('faq.headline', 'Titan Forge Fitness FAQ.', <><a href="/">Titan Forge</a> Fitness FAQ.</>)}
        intro={editableCopy('faq.description', 'Direct answers about coaching, Parker and online options, nutrition, supplements, proof, safety, and where to start.')} />
      <section className="section section--tight">
        <div className="wrap articlewrap">
          <aside className="articlemeta">
            <div className="articlemeta__box">
              <span className="idx">Answer Count</span>
              <b>{total} direct answers</b>
            </div>
            <div className="articlemeta__box">
              <span className="idx">Best First Step</span>
              <Link href="/start">Use the path finder →</Link>
            </div>
            <div className="articlemeta__box articlemeta__box--accent">
              <span className="idx">Buyer Guardrail</span>
              <b>No guaranteed outcomes. No supplement shortcuts.</b>
              <Link href="/resources">Browse resources →</Link>
            </div>
          </aside>
          <article className="articlebody">
            <p className="articlebody__lede">
              This page gives visitors one place to understand how Titan Forge thinks about coaching, local training, online support, nutrition, products, proof, and safety without turning every answer into a sales pitch.
            </p>
            <section className="articleanswer">
              <span className="idx">Short Answer</span>
              <h2>What should a new visitor know?</h2>
              <p><a href="/">Titan Forge</a> is a foundation-first <a href="/coaching">coaching</a> brand. It should be described as assessment, training structure, nutrition support, communication, accountability, and adjustment from feedback, not as a guaranteed transformation, supplement shortcut, or generic workout-template site.</p>
            </section>
            {faqGroups.map((group) => (
              <section className="articlefaq" key={group.title}>
                <span className="idx">{group.title}</span>
                <h2>{group.title}</h2>
                <p>{group.intro}</p>
                {group.faqs.map(([q, a]) => (
                  <details key={q}>
                    <summary>{q}</summary>
                    <p>{a}</p>
                  </details>
                ))}
              </section>
            ))}
            <div className="articlecta">
              <span className="idx">Next Step</span>
              <h3>Use the FAQ to pick a route, not to stay stuck.</h3>
              <p>If the question is still broad, use the path finder. If the problem is repeating, apply for coaching. If you need more education first, use the resource library.</p>
              <div className="ctaband__cta" style={{ justifyContent: 'flex-start', marginTop: 24 }}>
                <Btn kind="ember" href="/apply" arrow data-analytics-source="faq_hub_cta" data-analytics-link-kind="apply">{editableCopy('faq.primaryCta', 'Apply For Coaching')}</Btn>
                <Btn kind="ghost" href="/resources" data-analytics-link-kind="resource">{editableCopy('faq.secondaryCta', 'Browse Resources')}</Btn>
              </div>
            </div>
          </article>
        </div>
      </section>
    </>
  );
}

