/* Renders a guide from globalThis.TITAN_GUIDES, the same object
   app/lib/staticRouteContent.mjs renders into the crawler body. One author
   surface, two renderers. */
function guideForRoute(route) {
  const guides = (typeof globalThis !== 'undefined' && globalThis.TITAN_GUIDES) || {};
  return guides[route] || null;
}

function guideDateLabel(iso) {
  const [y, m, d] = String(iso).split('-').map(Number);
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  return `${d} ${months[m - 1]} ${y}`;
}

/* Protein calculator for /tools/protein-calculator. Ranges, sources and the unit
   conversion all come from the guide payload (app/lib/guideContentMagnets.mjs), so
   the table the crawler reads and the numbers this shows cannot differ. The form
   carries data-form-id and the goal select carries data-filter, which the shared
   analytics layer turns into form_start, form_submit and filter_apply without any
   bespoke event names. Nothing the visitor types leaves the browser. */
function ProteinTool({ tool }) {
  const [weight, setWeight] = useState('');
  const [unit, setUnit] = useState('lb');
  const [goalId, setGoalId] = useState(tool.goals[1].id);
  const [older, setOlder] = useState(false);
  const [shown, setShown] = useState(false);
  const goal = tool.goals.find((g) => g.id === goalId) || tool.goals[0];
  const entered = parseFloat(weight);
  const kg = unit === 'lb' ? entered * tool.kgPerLb : entered;
  const valid = Number.isFinite(kg) && kg >= 30 && kg <= 300;
  const [lowPer, highPer] = older ? goal.older : [goal.low, goal.high];
  const lowG = Math.round(kg * lowPer);
  const highG = Math.round(kg * highPer);
  const mealG = Math.round(kg * tool.perMeal.gramsPerKg);
  const perKg = lowPer === highPer ? `${lowPer.toFixed(1)} g/kg` : `${lowPer.toFixed(1)} to ${highPer.toFixed(1)} g/kg`;
  return (
    <section className="section section--tight">
      <div className="wrap">
        <form
          className="card proteintool"
          data-form-id="protein_calculator"
          onSubmit={(e) => { e.preventDefault(); setShown(true); }}
          noValidate
        >
          <span className="idx">{tool.title}</span>
          <div className="field__row">
            <div className="field">
              <label htmlFor="protein-weight">Body weight</label>
              <input id="protein-weight" name="weight" type="number" inputMode="decimal" min="1" step="any" placeholder={unit === 'lb' ? 'for example 180' : 'for example 82'} value={weight} onChange={(e) => setWeight(e.target.value)} />
            </div>
            <div className="field">
              <label htmlFor="protein-unit">Unit</label>
              <select id="protein-unit" name="unit" value={unit} onChange={(e) => setUnit(e.target.value)}>
                <option value="lb">Pounds</option>
                <option value="kg">Kilograms</option>
              </select>
            </div>
          </div>
          <div className="field">
            <label htmlFor="protein-goal">Goal</label>
            <select id="protein-goal" name="goal" data-filter="protein_goal" value={goalId} onChange={(e) => setGoalId(e.target.value)}>
              {tool.goals.map((g) => <option key={g.id} value={g.id}>{g.label}</option>)}
            </select>
          </div>
          <label className="proteintool__check">
            <input type="checkbox" name="older" checked={older} onChange={(e) => setOlder(e.target.checked)} />
            <span>I am 65 or older</span>
          </label>
          <button type="submit" className="btn btn--ember proteintool__go">Show my range</button>
          <div className="proteintool__result" aria-live="polite">
            {shown && !valid && <p className="proteintool__error">Enter a body weight between {unit === 'lb' ? '66 and 660 pounds' : '30 and 300 kilograms'}.</p>}
            {shown && valid && (
              <>
                <p className="proteintool__big"><strong>{lowG === highG ? `About ${lowG} g` : `${lowG} to ${highG} g`}</strong> of protein a day</p>
                <p className="proteintool__sub">That is {Math.round(kg)} kg of body weight at {perKg}. Per serving, about {mealG} g ({tool.perMeal.gramsPerKg} g/kg); the position statement cites {tool.perMeal.absoluteLow} to {tool.perMeal.absoluteHigh} g, spread roughly every {tool.perMeal.everyHours} hours (PMID 28642676).</p>
                <p className="proteintool__sub">{goal.basis}</p>
                <p className="proteintool__sub">If you have kidney disease or another medical condition, ask your clinician before you change how much protein you eat.</p>
              </>
            )}
          </div>
        </form>
      </div>
    </section>
  );
}

