function localCalendarDate(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

const DAILY_HABIT_STORAGE_KEY = 'titan_daily_habit';
const DAILY_HABITS = [
  { id: 'move', label: 'Move', detail: 'Make time for planned movement.' },
  { id: 'prepare', label: 'Prepare', detail: 'Set up one useful choice for later.' },
  { id: 'review', label: 'Review', detail: 'Take a brief note before the day ends.' },
];

function blankDailyHabitState(date = localCalendarDate()) {
  return { date, items: Object.fromEntries(DAILY_HABITS.map(({ id }) => [id, false])) };
}

function readDailyHabitState() {
  const fresh = blankDailyHabitState();
  try {
    const saved = JSON.parse(window.localStorage.getItem(DAILY_HABIT_STORAGE_KEY) || 'null');
    if (!saved || saved.date !== fresh.date || !saved.items) return fresh;
    return {
      date: fresh.date,
      items: Object.fromEntries(DAILY_HABITS.map(({ id }) => [id, Boolean(saved.items[id])])),
    };
  } catch {
    return fresh;
  }
}

function DailyHabitPage() {
  useReveal();
  const [daily, setDaily] = useState(null);
  const [email, setEmail] = useState('');
  const [emailSubmitted, setEmailSubmitted] = useState(false);

  useEffect(() => {
    setDaily(readDailyHabitState());
  }, []);

  useEffect(() => {
    if (!daily) return;
    try {
      window.localStorage.setItem(DAILY_HABIT_STORAGE_KEY, JSON.stringify(daily));
    } catch {}
  }, [daily]);

  const resetForToday = () => {
    const fresh = blankDailyHabitState();
    setDaily((current) => current?.date === fresh.date ? current : fresh);
    return fresh;
  };

  const toggleHabit = (id) => {
    const fresh = resetForToday();
    setDaily((current) => {
      const base = current?.date === fresh.date ? current : fresh;
      const completed = !base.items[id];
      window.titanTrackEvent && window.titanTrackEvent('daily_habit_toggle', {
        habit_id: id,
        completed,
        habit_date: base.date,
      });
      return { ...base, items: { ...base.items, [id]: completed } };
    });
  };

  const clearHabits = () => {
    const fresh = blankDailyHabitState();
    setDaily(fresh);
    window.titanTrackEvent && window.titanTrackEvent('daily_habit_clear', { habit_date: fresh.date });
  };

  const submitHabitEmail = (event) => {
    event.preventDefault();
    if (!/\S+@\S+\.\S+/.test(email)) return;
    setEmailSubmitted(true);
    window.titanTrackEvent && window.titanTrackEvent('daily_habit_email_submit', {
      form_id: 'daily_habit_email',
      source: 'daily_habit',
    });
  };

  const completeCount = daily ? Object.values(daily.items).filter(Boolean).length : 0;
  const preparedEmailHref = `mailto:Doc@titanforgefit.com?subject=${encodeURIComponent('Daily Habit email')}&body=${encodeURIComponent(`Please add this email to the daily habit list: ${email}`)}`;

  return (
    <>
      <PageHeader eyebrow="Daily Tool" title="Daily habit." intro="Choose a short list, check it off, and return tomorrow. Your daily state stays on this device." />
      <section className="section section--tight">
        <div className="wrap">
          <div className="dailyhabit card" data-analytics-source="daily_habit">
            <div className="dailyhabit__top">
              <div><span className="idx">Today</span><h2>{daily?.date || localCalendarDate()}</h2></div>
              <p aria-live="polite">{completeCount} of {DAILY_HABITS.length} checked</p>
            </div>
            <div className="dailyhabit__list" aria-label="Daily habit tracker">
              {DAILY_HABITS.map(({ id, label, detail }) => (
                <button key={id} type="button" className={`dailyhabit__item ${daily?.items[id] ? 'is-done' : ''}`} aria-pressed={Boolean(daily?.items[id])} onClick={() => toggleHabit(id)}>
                  <span className="dailyhabit__check" aria-hidden="true">{daily?.items[id] ? '✓' : ''}</span>
                  <span><b>{label}</b><small>{detail}</small></span>
                </button>
              ))}
            </div>
            <button className="dailyhabit__clear" type="button" onClick={clearHabits}>Clear today</button>
          </div>
        </div>
      </section>
      <section className="section section--inset">
        <div className="wrap dailyhabit__capture">
          <SectionHead eyebrow="Email" title="Keep this route handy." intro="Enter an email to prepare a direct handoff. This page has no delivery backend, so nothing is sent until you choose the email link." />
          {emailSubmitted ? (
            <div className="formdone" role="status">
              <h3>Prepared email</h3>
              <p>Use the link below to open your email app with the address included. No email is stored on this device by this form.</p>
              <a className="btn btn--ember" href={preparedEmailHref} data-analytics-event="daily_habit_email_fallback" data-analytics-source="daily_habit_email" data-analytics-link-kind="email_lead">Open prepared email <span className="arr">→</span></a>
            </div>
          ) : (
            <form onSubmit={submitHabitEmail} noValidate data-analytics-form="daily_habit_email" data-analytics-source="daily_habit_email">
              <div className="field"><label htmlFor="daily-habit-email">Email</label><input id="daily-habit-email" type="email" autoComplete="email" required value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@email.com" /></div>
              <Btn kind="ember" type="submit" arrow data-analytics-source="daily_habit_email" data-analytics-link-kind="email_lead">Prepare email</Btn>
            </form>
          )}
        </div>
      </section>
    </>
  );
}

/* ---- Daily Planner Page ---- */
const DAILY_PLANNER_STORAGE_KEY = 'titan_daily_planner_v1';

const DAILY_PLANNER_ANCHORS = [
  { id: 'protein', label: 'Protein Baseline Target', detail: 'Hit baseline protein intake (0.8–1.0g per lb target body weight across daily meals)' },
  { id: 'training', label: 'Training Session & Movement', detail: 'Completed scheduled strength training session or completed 30+ minutes of active movement' },
  { id: 'hydration', label: 'Hydration Target (80–120 oz)', detail: 'Drank target daily fluid intake to support workout capacity, focus, and recovery' },
  { id: 'sleep', label: 'Sleep & Recovery (7+ Hours)', detail: 'Logged 7+ hours of quality sleep and completed evening wind-down routine' },
  { id: 'reflection', label: 'Training Log & Notes', detail: 'Recorded workout numbers, sets, reps, or logged daily nutrition adherence notes' },
];

const DAILY_FOCUS_PROMPTS = [
  'Focus: Progressive Overload. Record your top working set weight and reps today. Small steady additions compound over months.',
  'Focus: Protein Consistency. Distribute 30–50g of protein across primary meals to support muscle protein synthesis.',
  'Focus: Hydration Baseline. Aim for 80–120 oz of fluid intake daily to support workout capacity and mental focus.',
  'Focus: Sleep & Recovery. Aim for 7–9 hours of sleep tonight. Quality rest underpins recovery and daily energy.',
  'Focus: Pre-Workout Fuel. Consume a moderate carb and protein meal 1–2 hours before training for sustained output.',
  'Focus: Post-Workout Recovery. Eat a high-protein meal or shake within 2 hours of completing your strength session.',
  'Focus: Warm-Up Discipline. Spend 5–10 minutes on dynamic mobility work before loading primary compound lifts.',
  'Focus: Form & Control. Prioritize controlled eccentrics and full range of motion over adding unnecessary weight.',
  'Focus: Step Count Baseline. Keep a steady baseline of daily movement alongside your structured lifting days.',
  'Focus: Rest Day Recovery. Use non-training days for active recovery, hydration, mobility, and consistent nutrition.',
];

function getDayOfYear(d = new Date()) {
  const start = new Date(d.getFullYear(), 0, 0);
  const diff = d - start;
  const oneDay = 1000 * 60 * 60 * 24;
  return Math.floor(diff / oneDay);
}

function blankDailyPlannerState() {
  const dateStr = localCalendarDate();
  return {
    date: dateStr,
    streak: 0,
    lastActiveDate: '',
    items: Object.fromEntries(DAILY_PLANNER_ANCHORS.map(({ id }) => [id, false])),
    weightLbs: '',
    note: '',
  };
}

function readDailyPlannerState() {
  const fresh = blankDailyPlannerState();
  if (typeof window === 'undefined') return fresh;
  try {
    const raw = window.localStorage.getItem(DAILY_PLANNER_STORAGE_KEY);
    if (!raw) return fresh;
    const saved = JSON.parse(raw);
    if (!saved || typeof saved !== 'object') return fresh;

    if (saved.date !== fresh.date) {
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      const yyyymmddYesterday = yesterday.toISOString().slice(0, 10);
      const isConsecutive = saved.date === yyyymmddYesterday || saved.lastActiveDate === yyyymmddYesterday;
      const currentStreak = isConsecutive ? (saved.streak || 0) : 0;

      return {
        ...fresh,
        streak: currentStreak,
        lastActiveDate: saved.date,
        weightLbs: saved.weightLbs || '',
      };
    }
    return {
      ...fresh,
      ...saved,
      items: Object.fromEntries(DAILY_PLANNER_ANCHORS.map(({ id }) => [id, Boolean(saved.items?.[id])])),
    };
  } catch {
    return fresh;
  }
}

function DailyPlannerPage() {
  useReveal();
  const [planner, setPlanner] = useState(null);
  const [email, setEmail] = useState('');
  const [emailSubmitted, setEmailSubmitted] = useState(false);

  useEffect(() => {
    setPlanner(readDailyPlannerState());
  }, []);

  useEffect(() => {
    if (!planner) return;
    try {
      window.localStorage.setItem(DAILY_PLANNER_STORAGE_KEY, JSON.stringify(planner));
    } catch {}
  }, [planner]);

  const toggleAnchor = (id) => {
    const freshDate = localCalendarDate();
    setPlanner((current) => {
      const base = current?.date === freshDate ? current : { ...blankDailyPlannerState(), streak: current?.streak || 0 };
      const nextCompleted = !base.items[id];
      const nextItems = { ...base.items, [id]: nextCompleted };
      const totalChecked = Object.values(nextItems).filter(Boolean).length;

      let nextStreak = base.streak || 0;
      let nextLastActive = base.lastActiveDate || '';
      if (totalChecked >= 3 && base.lastActiveDate !== freshDate) {
        nextStreak = (base.streak || 0) + 1;
        nextLastActive = freshDate;
      }

      window.titanTrackEvent && window.titanTrackEvent('daily_planner_anchor_toggle', {
        anchor_id: id,
        completed: nextCompleted,
        planner_date: freshDate,
        streak: nextStreak,
      });

      return {
        ...base,
        date: freshDate,
        items: nextItems,
        streak: nextStreak,
        lastActiveDate: nextLastActive,
      };
    });
  };

  const handleWeightChange = (e) => {
    const val = e.target.value;
    setPlanner((current) => ({ ...(current || blankDailyPlannerState()), weightLbs: val }));
  };

  const handleNoteChange = (e) => {
    const val = e.target.value;
    setPlanner((current) => ({ ...(current || blankDailyPlannerState()), note: val }));
  };

  const clearPlannerToday = () => {
    setPlanner((current) => {
      const fresh = blankDailyPlannerState();
      const updated = { ...fresh, streak: current?.streak || 0, weightLbs: current?.weightLbs || '' };
      window.titanTrackEvent && window.titanTrackEvent('daily_planner_clear', { planner_date: fresh.date });
      return updated;
    });
  };

  const submitPlannerEmail = (event) => {
    event.preventDefault();
    if (!/\S+@\S+\.\S+/.test(email)) return;
    setEmailSubmitted(true);
    window.titanTrackEvent && window.titanTrackEvent('daily_planner_email_submit', {
      form_id: 'daily_planner_email',
      source: 'daily_planner',
    });
  };

  const dayOfYear = getDayOfYear();
  const todayPrompt = DAILY_FOCUS_PROMPTS[dayOfYear % DAILY_FOCUS_PROMPTS.length];
  const completeCount = planner ? Object.values(planner.items).filter(Boolean).length : 0;

  const wLbs = parseFloat(planner?.weightLbs) || 0;
  const proteinLow = wLbs > 0 ? Math.round(wLbs * 0.8) : 0;
  const proteinHigh = wLbs > 0 ? Math.round(wLbs * 1.0) : 0;
  const waterOzLow = wLbs > 0 ? Math.round(wLbs * 0.6) : 0;
  const waterOzHigh = wLbs > 0 ? Math.round(wLbs * 0.75) : 0;

  const preparedEmailHref = `mailto:Doc@titanforgefit.com?subject=${encodeURIComponent('Daily Planner Handoff')}&body=${encodeURIComponent(`Daily Planner Email Handoff: ${email}`)}`;

  return (
    <>
      <PageHeader
        eyebrow="Daily Habit Surface"
        title="Daily Forge Planner."
        intro="Track your daily training, protein, hydration, and recovery anchors. Built to maintain your daily focus and streak locally on this device."
      />

      <section className="section section--tight">
        <div className="wrap">
          <div className="dailyhabit card" data-analytics-source="daily_planner">
            <div className="dailyhabit__top">
              <div>
                <span className="idx">Today — {planner?.date || localCalendarDate()}</span>
                <h2>Daily Anchors</h2>
              </div>
              <div style={{ textAlign: 'right' }}>
                <p aria-live="polite" style={{ marginBottom: 4 }}><b>{completeCount} of {DAILY_PLANNER_ANCHORS.length}</b> completed</p>
                <span className="chip" style={{ background: 'rgba(226,85,46,0.12)', color: 'var(--ember)', border: '1px solid var(--ember)' }}>
                  🔥 {planner?.streak || 0} Day Streak
                </span>
              </div>
            </div>

            <div className="dailyplanner__prompt card" style={{ background: 'var(--bg-2)', padding: '16px 20px', borderRadius: 'var(--r-sm)', marginBottom: 20, borderLeft: '3px solid var(--ember)' }}>
              <span className="idx" style={{ fontSize: 11, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--ember)', fontWeight: 600 }}>Daily Focus Prompt</span>
              <p style={{ margin: '4px 0 0', fontSize: 15, color: 'var(--text-1)', lineHeight: 1.5 }}>{todayPrompt}</p>
            </div>

            <div className="dailyhabit__list" aria-label="Daily planner anchors">
              {DAILY_PLANNER_ANCHORS.map(({ id, label, detail }) => (
                <button
                  key={id}
                  type="button"
                  className={`dailyhabit__item ${planner?.items[id] ? 'is-done' : ''}`}
                  aria-pressed={Boolean(planner?.items[id])}
                  onClick={() => toggleAnchor(id)}
                >
                  <span className="dailyhabit__check" aria-hidden="true">{planner?.items[id] ? '✓' : ''}</span>
                  <span>
                    <b>{label}</b>
                    <small>{detail}</small>
                  </span>
                </button>
              ))}
            </div>

            <div style={{ marginTop: 28, paddingTop: 24, borderTop: '1px solid var(--line-2)' }}>
              <h3 style={{ fontSize: 18, textTransform: 'uppercase', marginBottom: 12 }}>Target Quick Calculator</h3>
              <p style={{ fontSize: 14, color: 'var(--text-3)', marginBottom: 16 }}>Enter body weight (lbs) to derive daily protein and hydration targets grounded in Titan Forge guidelines.</p>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 16, alignItems: 'center' }}>
                <div className="field" style={{ margin: 0 }}>
                  <label htmlFor="daily-planner-weight" style={{ fontSize: 13 }}>Body Weight (lbs)</label>
                  <input
                    id="daily-planner-weight"
                    type="number"
                    min="80"
                    max="400"
                    value={planner?.weightLbs || ''}
                    onChange={handleWeightChange}
                    placeholder="e.g. 185"
                  />
                </div>
                {wLbs > 0 && (
                  <div style={{ background: 'var(--bg-2)', padding: '12px 16px', borderRadius: 'var(--r-sm)', border: '1px solid var(--line-2)' }}>
                    <div style={{ fontSize: 13, color: 'var(--text-2)' }}><b>Protein Target:</b> {proteinLow}–{proteinHigh}g / day</div>
                    <div style={{ fontSize: 13, color: 'var(--text-2)', marginTop: 4 }}><b>Water Target:</b> {waterOzLow}–{waterOzHigh} oz / day</div>
                  </div>
                )}
              </div>
            </div>

            <div style={{ marginTop: 24, paddingTop: 20, borderTop: '1px solid var(--line-2)' }}>
              <div className="field">
                <label htmlFor="daily-planner-note" style={{ fontSize: 13 }}>Daily Reflection / Training Note</label>
                <textarea
                  id="daily-planner-note"
                  rows={2}
                  value={planner?.note || ''}
                  onChange={handleNoteChange}
                  placeholder="Record top lifts, set numbers, or daily adherence notes..."
                  style={{ width: '100%', padding: '12px', background: 'var(--bg-2)', color: 'var(--text-1)', border: '1px solid var(--line-2)', borderRadius: 'var(--r-sm)' }}
                />
              </div>
            </div>

            <button className="dailyhabit__clear" type="button" onClick={clearPlannerToday}>
              Clear today's checklist
            </button>
          </div>
        </div>
      </section>

      <section className="section section--inset">
        <div className="wrap dailyhabit__capture">
          <SectionHead
            eyebrow="Email Digest"
            title="Keep this daily planner accessible."
            intro="Enter an email to prepare a direct handoff for daily reminders. State remains stored locally on this device."
          />
          {emailSubmitted ? (
            <div className="formdone" role="status">
              <h3>Prepared Handoff Email</h3>
              <p>Use the link below to open your email client with your address prepared. No server database is used by this form.</p>
              <a
                className="btn btn--ember"
                href={preparedEmailHref}
                data-analytics-event="daily_planner_email_fallback"
                data-analytics-source="daily_planner_email"
                data-analytics-link-kind="email_lead"
              >
                Open Prepared Email <span className="arr">→</span>
              </a>
            </div>
          ) : (
            <form
              onSubmit={submitPlannerEmail}
              noValidate
              data-analytics-form="daily_planner_email"
              data-analytics-source="daily_planner_email"
            >
              <div className="field">
                <label htmlFor="daily-planner-email">Email Address</label>
                <input
                  id="daily-planner-email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(event) => setEmail(event.target.value)}
                  placeholder="you@email.com"
                />
              </div>
              <Btn
                kind="ember"
                type="submit"
                arrow
                data-analytics-source="daily_planner_email"
                data-analytics-link-kind="email_lead"
              >
                Prepare Daily Reminder Handoff
              </Btn>
            </form>
          )}
        </div>
      </section>
    </>
  );
}

/* ---- Daily Log Page ---- */
const DAILY_LOG_STORAGE_KEY = 'titan_daily_log_v1';

const DAILY_LOG_ANCHORS = [
  { id: 'workout', label: 'Daily Session & Movement', detail: 'Completed scheduled strength session, conditioning, or active mobility work' },
  { id: 'protein', label: 'Protein Target (0.8–1.0g/lb)', detail: 'Hit baseline daily protein target across primary meals to support muscle synthesis' },
  { id: 'hydration', label: 'Hydration Target (80–120 oz)', detail: 'Drank target daily fluid intake to support workout output and recovery' },
  { id: 'recovery', label: 'Sleep & Rest (7+ Hours)', detail: 'Logged 7+ hours of quality sleep and completed evening wind-down routine' },
  { id: 'notes', label: 'Training Log & Notes', detail: 'Recorded top set weight, reps, RPE, or logged daily adherence notes' },
];

const DAILY_LOG_PROMPTS = [
  'Focus: Progressive Overload. Record your top working set weight and reps today. Small steady additions compound over months.',
  'Focus: Protein Consistency. Distribute 30–50g of protein across primary meals to support muscle protein synthesis.',
  'Focus: Hydration Baseline. Aim for 80–120 oz of fluid intake daily to support workout capacity and mental focus.',
  'Focus: Sleep & Recovery. Aim for 7–9 hours of sleep tonight. Quality rest underpins recovery and daily energy.',
  'Focus: Pre-Workout Fuel. Consume a moderate carb and protein meal 1–2 hours before training for sustained output.',
  'Focus: Post-Workout Recovery. Eat a high-protein meal or shake within 2 hours of completing your strength session.',
  'Focus: Form & Control. Prioritize controlled eccentrics (2-3 seconds) over adding weight with poor mechanics.',
  'Focus: Active Recovery. Use non-lifting days for light walking, mobility work, hydration, and consistent nutrition.',
  'Focus: Step Count Baseline. Keep a steady daily movement baseline alongside your structured training days.',
  'Focus: Evening Wind-Down. Dim lights and limit screens 30 minutes before bed to protect sleep quality.',
];

function blankDailyLogState() {
  const dateStr = localCalendarDate();
  return {
    date: dateStr,
    streak: 0,
    lastActiveDate: '',
    items: Object.fromEntries(DAILY_LOG_ANCHORS.map(({ id }) => [id, false])),
    exerciseName: '',
    topWeightLbs: '',
    topReps: '',
    rpe: '8',
    fluidOz: 0,
    note: '',
  };
}

function readDailyLogState() {
  const fresh = blankDailyLogState();
  if (typeof window === 'undefined') return fresh;
  try {
    const raw = window.localStorage.getItem(DAILY_LOG_STORAGE_KEY);
    if (!raw) return fresh;
    const saved = JSON.parse(raw);
    if (!saved || typeof saved !== 'object') return fresh;

    if (saved.date !== fresh.date) {
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      const yyyymmddYesterday = yesterday.toISOString().slice(0, 10);
      const isConsecutive = saved.date === yyyymmddYesterday || saved.lastActiveDate === yyyymmddYesterday;
      const currentStreak = isConsecutive ? (saved.streak || 0) : 0;

      return {
        ...fresh,
        streak: currentStreak,
        lastActiveDate: saved.date,
        exerciseName: saved.exerciseName || '',
        topWeightLbs: saved.topWeightLbs || '',
        topReps: saved.topReps || '',
      };
    }
    return {
      ...fresh,
      ...saved,
      items: Object.fromEntries(DAILY_LOG_ANCHORS.map(({ id }) => [id, Boolean(saved.items?.[id])])),
    };
  } catch {
    return fresh;
  }
}

function DailyLogPage() {
  useReveal();
  const [logState, setLogState] = useState(null);

  useEffect(() => {
    setLogState(readDailyLogState());
  }, []);

  useEffect(() => {
    if (!logState) return;
    try {
      window.localStorage.setItem(DAILY_LOG_STORAGE_KEY, JSON.stringify(logState));
    } catch {}
  }, [logState]);

  const toggleAnchor = (id) => {
    const freshDate = localCalendarDate();
    setLogState((current) => {
      const base = current?.date === freshDate ? current : { ...blankDailyLogState(), streak: current?.streak || 0 };
      const nextCompleted = !base.items[id];
      const nextItems = { ...base.items, [id]: nextCompleted };
      const anyCompleted = Object.values(nextItems).some(Boolean);
      let nextStreak = base.streak;

      if (anyCompleted && base.lastActiveDate !== freshDate) {
        nextStreak = (base.streak || 0) + 1;
      } else if (!anyCompleted && base.lastActiveDate === freshDate) {
        nextStreak = Math.max(0, (base.streak || 1) - 1);
      }

      const updated = {
        ...base,
        date: freshDate,
        items: nextItems,
        streak: nextStreak,
        lastActiveDate: anyCompleted ? freshDate : (base.lastActiveDate === freshDate ? '' : base.lastActiveDate),
      };

      if (typeof window !== 'undefined') {
        window.titanTrackEvent && window.titanTrackEvent('daily_log_anchor_toggle', {
          anchor_id: id,
          completed: nextCompleted,
          log_date: freshDate,
          streak: nextStreak,
        });
      }
      return updated;
    });
  };

  const addFluid = (amountOz) => {
    setLogState((current) => {
      if (!current) return current;
      const nextOz = Math.min(200, Math.max(0, (current.fluidOz || 0) + amountOz));
      const nextItems = { ...current.items, hydration: nextOz >= 80 };
      return { ...current, fluidOz: nextOz, items: nextItems };
    });
  };

  const updateField = (field, value) => {
    setLogState((current) => (current ? { ...current, [field]: value } : current));
  };

  const clearToday = () => {
    const fresh = blankDailyLogState();
    setLogState((current) => ({
      ...fresh,
      streak: current?.streak || 0,
      lastActiveDate: current?.lastActiveDate || '',
    }));
    if (typeof window !== 'undefined') {
      window.titanTrackEvent && window.titanTrackEvent('daily_log_clear', { log_date: fresh.date });
    }
  };

  if (!logState) return null;

  const promptIndex = getDayOfYear() % DAILY_LOG_PROMPTS.length;
  const todayPrompt = DAILY_LOG_PROMPTS[promptIndex];
  const completeCount = Object.values(logState.items).filter(Boolean).length;

  return (
    <>
      <section className="hero hero--sub hero--reveal">
        <div className="contain">
          <span className="eyebrow card__tag">Daily Habit Engine</span>
          <h1 className="h1--sub">Daily Forge Log</h1>
          <p className="hero__p">
            Track daily training sessions, top set numbers, nutrition targets, hydration, and recovery anchors locally on this device.
          </p>
        </div>
      </section>

      <section className="sec sec--reveal">
        <div className="contain contain--narrow">
          <div className="dailyhabit card" data-analytics-source="daily_log">
            <div className="dailyhabit__head">
              <div>
                <h2 style={{ fontSize: '1.4rem', marginBottom: 4 }}>Daily Progress &amp; Anchors</h2>
                <p style={{ margin: 0, color: 'var(--muted)', fontSize: '0.9rem' }}>Date: <b>{logState.date}</b></p>
              </div>
              <div className="dailyhabit__streak" aria-label={`Current streak: ${logState.streak} days`}>
                <span className="dailyhabit__flame">🔥</span>
                <span><b>{logState.streak}</b> Day Streak</span>
              </div>
            </div>

            <div style={{ margin: '16px 0 20px', padding: '12px 16px', background: 'rgba(255,255,255,0.03)', borderRadius: 8, borderLeft: '3px solid var(--accent)' }}>
              <p aria-live="polite" style={{ marginBottom: 4 }}><b>{completeCount} of {DAILY_LOG_ANCHORS.length}</b> anchors completed</p>
              <p style={{ margin: 0, fontSize: '0.9rem', color: 'var(--muted)' }}>{todayPrompt}</p>
            </div>

            <div className="dailyhabit__list">
              {DAILY_LOG_ANCHORS.map(({ id, label, detail }) => (
                <button
                  key={id}
                  type="button"
                  className={`dailyhabit__item ${logState.items[id] ? 'dailyhabit__item--done' : ''}`}
                  onClick={() => toggleAnchor(id)}
                  aria-pressed={Boolean(logState.items[id])}
                  data-analytics-event="daily_log_anchor_click"
                  data-analytics-anchor={id}
                >
                  <span className="dailyhabit__box">{logState.items[id] ? '✓' : ''}</span>
                  <span className="dailyhabit__text">
                    <b>{label}</b>
                    <small>{detail}</small>
                  </span>
                </button>
              ))}
            </div>

            <div style={{ marginTop: 24, paddingTop: 20, borderTop: '1px solid rgba(255,255,255,0.08)' }}>
              <h3 style={{ fontSize: '1.1rem', marginBottom: 12 }}>Top Working Set Log</h3>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: 12, marginBottom: 16 }}>
                <div>
                  <label htmlFor="daily-log-exercise" style={{ display: 'block', fontSize: '0.8rem', color: 'var(--muted)', marginBottom: 4 }}>Exercise Name</label>
                  <input
                    id="daily-log-exercise"
                    type="text"
                    value={logState.exerciseName}
                    onChange={(e) => updateField('exerciseName', e.target.value)}
                    placeholder="e.g. Back Squat"
                    style={{ width: '100%', padding: '8px 12px', borderRadius: 6, background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff' }}
                  />
                </div>
                <div>
                  <label htmlFor="daily-log-weight" style={{ display: 'block', fontSize: '0.8rem', color: 'var(--muted)', marginBottom: 4 }}>Weight (Lbs)</label>
                  <input
                    id="daily-log-weight"
                    type="number"
                    value={logState.topWeightLbs}
                    onChange={(e) => updateField('topWeightLbs', e.target.value)}
                    placeholder="225"
                    style={{ width: '100%', padding: '8px 12px', borderRadius: 6, background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff' }}
                  />
                </div>
                <div>
                  <label htmlFor="daily-log-reps" style={{ display: 'block', fontSize: '0.8rem', color: 'var(--muted)', marginBottom: 4 }}>Reps Completed</label>
                  <input
                    id="daily-log-reps"
                    type="number"
                    value={logState.topReps}
                    onChange={(e) => updateField('topReps', e.target.value)}
                    placeholder="5"
                    style={{ width: '100%', padding: '8px 12px', borderRadius: 6, background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff' }}
                  />
                </div>
              </div>

              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 16 }}>
                <div>
                  <span style={{ fontSize: '0.85rem', color: 'var(--muted)' }}>Hydration Logged: </span>
                  <b>{logState.fluidOz} oz</b>
                </div>
                <div style={{ display: 'flex', gap: 8 }}>
                  <button
                    type="button"
                    onClick={() => addFluid(16)}
                    style={{ padding: '6px 12px', borderRadius: 6, background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.15)', color: '#fff', fontSize: '0.85rem', cursor: 'pointer' }}
                  >
                    +16 oz
                  </button>
                  <button
                    type="button"
                    onClick={() => addFluid(32)}
                    style={{ padding: '6px 12px', borderRadius: 6, background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.15)', color: '#fff', fontSize: '0.85rem', cursor: 'pointer' }}
                  >
                    +32 oz
                  </button>
                </div>
              </div>
            </div>

            <div className="dailyhabit__foot">
              <button type="button" className="dailyhabit__clear" onClick={clearToday}>Reset Today</button>
              <span className="dailyhabit__storage">Stored locally in your browser</span>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}

