/* ---------------------- CONTACT ---------------------- */
function ContactPage() {
  useReveal();
  const [sent, setSent] = useState(false);
  const [leadEvent, setLeadEvent] = useState(null);
  const [form, setForm] = useState({
    name: '',
    email: '',
    goal: 'Lose fat',
    path: 'Online coaching',
    blocker: 'consistency',
    schedule: 'twoToThree',
    support: 'fullCoaching',
  });
  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));
  const valid = form.name.trim() && /\S+@\S+\.\S+/.test(form.email);
  const submit = async (e) => {
    e.preventDefault();
    if (!valid) {
      window.titanTrackEvent && window.titanTrackEvent('apply_form_invalid_submit', {
        form_id: 'intro_call',
        has_name: Boolean(form.name.trim()),
        has_email: Boolean(form.email.trim()),
      });
      return;
    }
    window.titanTrackEvent && window.titanTrackEvent('apply_form_valid_submit', {
      form_id: 'intro_call',
      primary_goal: form.goal,
      starting_path: form.path,
    });
    const leadResult = await postLeadEvent({ ...form, coach: 'steve' }, 'intro call request');
    setLeadEvent(leadResult);
    window.titanTrackEvent && window.titanTrackEvent('lead_server_submit', {
      form_id: 'intro_call',
      ok: Boolean(leadResult.ok),
      lead_id: leadResult.leadId,
    });
    if (leadResult.ok) setSent(true);
  };
  return (
    <>
      <PageHeader eyebrow="Contact" title="Request your free intro call."
        intro={<>Tell us a little about where you are. The first step is a no-pressure conversation to figure out whether <a href="/">Titan Forge</a> is the right fit.</>}>
        <div className="ctaband__cta" style={{ justifyContent: 'flex-start', marginTop: 24 }}>
          <a className="btn btn--ember" href={STEVE_CALENDLY_URL} target="_blank" rel="noreferrer" data-analytics-event="coach_booking_click" data-analytics-source="contact_header" data-analytics-link-kind="booking">Book Steve Intro Call <span className="arr">→</span></a>
        </div>
        <p className="microcopy" style={{ marginTop: 12 }}>Already ready to talk? Pick a time. Prefer to share context first? Use the form below.</p>
      </PageHeader>
      <section className="section">
        <div className="wrap contact">
          <div>
            {sent ? (
              <div className="formdone">
                <div style={{ fontFamily: 'var(--display)', fontSize: 44, color: 'var(--ember)' }}>✓</div>
                <h3>Intro request ready.</h3>
                <p>{leadEvent?.ownerDelivered
                  ? `Thanks, ${form.name.split(' ')[0] || 'there'}. Your intro request was delivered to Titan Forge. You can pick a time with Steve now.`
                  : `Thanks, ${form.name.split(' ')[0] || 'there'}. Automatic owner delivery did not complete. You can book Steve directly now, then send the prepared email if you want him to receive your context before the call.`}</p>
                {leadEvent?.ok && <p className="microcopy">Reference: {leadEvent.leadId}</p>}
                <div className="ctaband__cta" style={{ justifyContent: 'flex-start', marginTop: 26 }}>
                  <a className="btn btn--ember" href={STEVE_CALENDLY_URL} target="_blank" rel="noreferrer" data-analytics-event="coach_booking_click" data-analytics-source="contact_success" data-analytics-link-kind="booking">Book Steve Intro Call <span className="arr">→</span></a>
                  {!leadEvent?.ownerDelivered && <a className="btn btn--ghost" href={leadEmailHref({ ...form, coach: 'steve' }, 'intro call request')} data-analytics-event="lead_email_click" data-analytics-source="contact_success" data-analytics-link-kind="email_lead">Send Context to Steve <span className="arr">→</span></a>}
                  <Btn kind="ghost" href="/" onClick={() => setSent(false)}>Back to home</Btn>
                </div>
              </div>
            ) : (
              <form onSubmit={submit} noValidate data-analytics-form="intro_call" data-analytics-source="intro_call_form">
                <div className="field__row">
                  <div className="field"><label htmlFor="contact-name">Name</label><input id="contact-name" autoComplete="name" required aria-invalid={!form.name.trim()} value={form.name} onChange={set('name')} placeholder="Your name" /></div>
                  <div className="field"><label htmlFor="contact-email">Email</label><input id="contact-email" type="email" autoComplete="email" required aria-invalid={Boolean(form.email && !/\S+@\S+\.\S+/.test(form.email))} value={form.email} onChange={set('email')} placeholder="you@email.com" /></div>
                </div>
                <div className="field__row">
                  <div className="field"><label htmlFor="contact-goal">Primary Goal</label>
                    <select id="contact-goal" value={form.goal} onChange={set('goal')}>
                      <option>Lose fat</option><option>Build muscle</option><option>Get stronger</option><option>Fix nutrition</option><option>General health</option>
                    </select>
                  </div>
                  <div className="field"><label htmlFor="contact-path">Interested In</label>
                    <select id="contact-path" value={form.path} onChange={set('path')}>
                      <option>Online coaching</option><option>In-person training</option><option>Nutrition coaching</option><option>Programs</option><option>Not sure yet</option>
                    </select>
                  </div>
                </div>
                <div className="field__row">
                  <div className="field"><label htmlFor="contact-blocker">Main Problem</label>
                    <select id="contact-blocker" value={form.blocker} onChange={set('blocker')}>
                      <option value="consistency">Consistency</option>
                      <option value="nutrition">Nutrition</option>
                      <option value="trainingPlan">Training plan</option>
                      <option value="schedule">Schedule</option>
                      <option value="accountability">Accountability</option>
                      <option value="confidence">Confidence / gym anxiety</option>
                    </select>
                  </div>
                  <div className="field"><label htmlFor="contact-schedule">Weekly Schedule</label>
                    <select id="contact-schedule" value={form.schedule} onChange={set('schedule')}>
                      <option value="twoToThree">2 to 3 sessions per week</option>
                      <option value="fourPlus">4 or more sessions per week</option>
                      <option value="variable">Schedule changes week to week</option>
                      <option value="notSure">Not sure yet</option>
                    </select>
                  </div>
                </div>
                <div className="field"><label htmlFor="contact-support">What kind of support do you want most?</label>
                  <select id="contact-support" value={form.support} onChange={set('support')}>
                    <option value="fullCoaching">Full coaching and accountability</option>
                    <option value="technique">Technique and exercise guidance</option>
                    <option value="nutritionSupport">Nutrition support</option>
                    <option value="simplePlan">Simple starting plan</option>
                    <option value="notSure">Not sure yet</option>
                  </select>
                </div>
                <Btn kind="ember" arrow className={valid ? '' : ''} type="submit">Request My Intro Call</Btn>
                {!valid && <p style={{ fontFamily: 'var(--mono)', fontSize: 11.5, letterSpacing: '0.08em', color: 'var(--text-3)', marginTop: 14 }}>Add your name and a valid email to continue.</p>}
                {leadEvent && !leadEvent.ok && <p role="alert" style={{ marginTop: 14 }}>We could not save the intro request yet. Please retry, or email Doc@titanforgefit.com directly.</p>}
              </form>
            )}
          </div>
          <aside className="contact__aside">
            <h3>Or reach us directly.</h3>
            <div className="contact__line"><b>Location</b><span>Englewood, CO · Online worldwide</span></div>
            <div className="contact__line"><b>Email</b><a href="mailto:Doc@titanforgefit.com" data-analytics-source="contact_direct" data-analytics-link-kind="email_direct">Doc@titanforgefit.com</a></div>
            <div className="contact__line"><b>Instagram</b><a href="https://www.instagram.com/doc.gymlifts/" target="_blank" rel="noreferrer">@doc.gymlifts</a></div>
            <div className="contact__line"><b>Hours</b><span>Mon–Fri · Intro calls by appointment</span></div>
            <div className="contact__line"><b>Response</b><span>Follow-up after intro request review</span></div>
            <div style={{ marginTop: 30 }} className="notice">
              <span className="notice__mark">◆</span>
              <div>
                <h3 style={{ fontSize: 18 }}>No pressure, ever.</h3>
                <p>The intro call is a conversation, not a sales pitch. If we’re not the right fit, we’ll say so.</p>
              </div>
            </div>
          </aside>
        </div>
      </section>
      <FAQSection route="/contact" />
    </>
  );
}

