function readWeeklyHandoffState() {
  const empty = { steve: {}, kris: {}, gonzalo: {} };
  try {
    const saved = JSON.parse(window.localStorage.getItem(WEEKLY_HANDOFF_STORAGE_KEY) || 'null');
    const normalize = (owner) => Object.fromEntries(Object.entries(saved?.[owner] || {}).map(([key, value]) => [key, value === true ? { event_kind: 'completed', occurred_at: null, actor: 'Saved locally' } : value]));
    return saved && typeof saved === 'object' ? { ...empty, ...saved, steve: normalize('steve'), kris: normalize('kris'), gonzalo: normalize('gonzalo') } : empty;
  } catch { return empty; }
}

