function TaskInstructions({ owner, task, detail }) {
  const content = (() => {
    const disposition = WEEKLY_HANDOFF.sourceDispositions?.[owner]?.[task];
    if (disposition) return <><h4>Meeting update</h4><p>This item is no longer an open action in the current meeting notes. Keep it here as a record; no further work is requested unless it is reopened.</p></>;
    if (FILMING_TASKS[owner] === task && !WEEKLY_HANDOFF.taskOverrides?.[owner]?.[task]) return <FilmingInstructions owner={owner} />;
    const entry = WEEKLY_HANDOFF.taskOverrides?.[owner]?.[task] || (TASK_INSTRUCTIONS[owner] && TASK_INSTRUCTIONS[owner][task]) || WEEKLY_HANDOFF.instructions?.[owner]?.[task];
    // A task with no written entry still renders from its own detail line. A new
    // task must never be able to blank the board.
    const [steps, done] = entry || [detail, null];
    return <><h4>How to do it</h4><p>{steps}</p>{done ? <><h4>Done when</h4><p>{done}</p></> : null}</>;
  })();
  return <div className="task-detail">{content}</div>;
}

function TaskLinks({ title, items, linkLabel }) {
  return <><h4>{title}</h4><div className="task-detail__cards">{items.map((item) => <article key={item.href}><span>{item.label}</span><b>{item.title}</b><p>{item.action}</p><a href={item.href} target="_blank" rel="noreferrer">{linkLabel} →</a></article>)}</div></>;
}

