function WeeklyDataSection({ weekKey }) {
  const [data, setData] = useState(undefined);
  useEffect(() => {
    setData(undefined);
    fetch(`/weekly-data/${weekKey}.json`).then((r) => (r.ok ? r.json() : Promise.reject())).then(setData).catch(() => setData(null));
  }, [weekKey]);
  if (data === undefined) return null;
  if (data === null) return <section className="section"><div className="wrap"><SectionHead eyebrow="The numbers" title="No numbers were collected for that week." intro="The weekly numbers were not captured, so there is nothing to compare. Nothing is missing from the board itself." /></div></section>;
  const titan = data.ga4?.titan; const geebs = data.ga4?.geebs;
  const ig = (data.geebs_social?.by_network || []).find((n) => n.network === 'instagram');
  const yt = (data.geebs_social?.by_network || []).find((n) => n.network === 'youtube');
  const best = data.geebs_social?.best_post;
  const bot = data.bot || {};
  const titanQ = data.search?.titanforge; const geebsQ = data.search?.geebs;
  const titanG = data.gsc?.titan?.top_queries?.[0]; const geebsG = data.gsc?.geebs?.top_queries?.[0];
  const pillarNames = PILLAR_NAMES;
  const Card = ({ title, children }) => <article className="task-detail__cards" style={{ display: 'block' }}><article><b>{title}</b>{children}</article></article>;
  // 2026-10-14 (Gonzalo): "why is this stale?" It was not stale. It was called
  // "This week's data" while showing the last COMPLETE week, under a board
  // headed with the current week, and it promised a Friday refresh that does
  // not happen (the snapshot behind this was generated on a Sunday). Both
  // claims were typed by hand. Every date here now comes out of the snapshot's
  // own range/generated_at, so the dates on screen cannot disagree with the
  // numbers behind them, and no cadence is promised at all.
  const windowCovered = fmtRange(data.range);
  const windowPrior = fmtRange({ current: data.range?.prior });
  const collectedOn = data.generated_at
    ? new Date(`${String(data.generated_at).slice(0, 10)}T12:00:00`).toLocaleDateString([], { month: 'short', day: 'numeric' })
    : '';
  return <section className="section" aria-label="The numbers for the last full week">
    <div className="wrap">
      <SectionHead eyebrow="The numbers" title={windowCovered ? `The last full week: ${windowCovered}.` : 'The last full week.'}
        intro={`${windowCovered ? `Every number here covers ${windowCovered}` : 'Every number here covers the last full week'}${windowPrior ? `, compared with ${windowPrior}` : ', compared with the week before it'}. It is the most recent complete seven days, so the week this board is for is not in these numbers yet.${collectedOn ? ` Collected ${collectedOn}.` : ''}`} />
      <div className="task-detail__cards">
        <article>
          <span>Titan Forge — Website</span>
          <b>{titan ? `${titan.cur.sessions.toLocaleString()} visits` : 'No data'}</b>
          {titan && <p>People who opened titanforgefit.com this week<DeltaWord cur={titan.cur.sessions} prior={titan.prior.sessions} />.</p>}
          <TrendLine trend={data.trends?.titan_website} />
          {titanG ? <p>Top Google search bringing people in: “{titanG.query}” ({titanG.clicks} clicks this week).</p> : titanQ?.top_queries?.[0] && <p>Top Google search bringing people in: “{titanQ.top_queries[0].query}” (ranked #{titanQ.top_queries[0].position}).</p>}
        </article>
        <article>
          <span>Titan Forge — Social</span>
          <b>{data.titan_social_connected ? (data.titan_social_posts_in_window ? `${data.titan_social_posts_in_window} posts published` : 'Connected — no posts published') : data.titan_social_connected === false ? 'Not connected yet' : 'Connection not verified'}</b>
          {data.titan_social_connected
            ? <p>{data.titan_social_posts_in_window ? 'Titan Forge social posts published this week.' : `The Titan Forge accounts (${(data.titan_social_networks || []).join(', ')}) are connected to Metricool, but nothing was posted this week — so there are no numbers to show yet. That changes as soon as posting starts.`}</p>
            : <p>Titan Forge social accounts are not connected to Metricool yet, so there are no Titan social numbers to show. This is a setup gap, not a zero.</p>}
          <TrendLine trend={data.trends?.titan_social} />
        </article>
        <article>
          <span>Gains From Geebs — Website</span>
          <b>{geebs ? `${geebs.cur.sessions.toLocaleString()} visits` : 'No data'}</b>
          {geebs && <p>People who opened gainsfromgeebs.com this week<DeltaWord cur={geebs.cur.sessions} prior={geebs.prior.sessions} />.</p>}
          <TrendLine trend={data.trends?.geebs_website} />
          {geebsG ? <p>Top Google search bringing people in: “{geebsG.query}” ({geebsG.clicks} clicks this week).</p> : geebsQ?.top_queries?.[0] && <p>Top Google search bringing people in: “{geebsQ.top_queries[0].query}” (ranked #{geebsQ.top_queries[0].position}).</p>}
        </article>
        <article>
          <span>Gains From Geebs — Social</span>
          <b>{ig ? `${Number(ig.posts) + Number(yt?.posts || 0)} posts published` : 'No data'}</b>
          {ig && <p>Instagram: reached {Number(ig.reach).toLocaleString()} people, {Number(ig.saves).toLocaleString()} saves.{yt ? ` YouTube: ${Number(yt.impressions).toLocaleString()} views.` : ''}</p>}
          {best && <p>Best post of the week: <a href={best.url} target="_blank" rel="noreferrer">this carousel</a> — reached {Number(best.reach).toLocaleString()} people.</p>}
          <TrendLine trend={data.trends?.geebs_social} />
        </article>
        <article>
          <span>DM Bot</span>
          <b>{bot.current ? `${bot.current.new_leads.toLocaleString()} new leads` : 'No data'}</b>
          {bot.current && <p>New people who messaged the bot this week<DeltaWord cur={bot.current.new_leads} prior={bot.prior?.new_leads} />.</p>}
          {bot.current && <p>Calls booked: {bot.current.bookings}<DeltaWord cur={bot.current.bookings} prior={bot.prior?.bookings} />. Handed to a coach: {bot.current.handed_off}.</p>}
          <TrendLine trend={data.trends?.dm_bot} />
        </article>
        <article>
          <span>What people ask</span>
          <b>Top topics in the DMs</b>
          {data.voc?.top_pillars && <p>{data.voc.top_pillars.slice(0, 3).map((p) => `${pillarNames[p.pillar] || p.pillar} (${p.count})`).join(' · ')}</p>}
          {(data.gsc?.geebs?.top_queries?.length || data.gsc?.titan?.top_queries?.length) ? <p>Top searches people find us with: {[...(data.gsc?.geebs?.top_queries || []).slice(0, 2), ...(data.gsc?.titan?.top_queries || []).slice(0, 1)].map((q) => `“${q.query}”`).join(', ')}.</p> : (titanQ?.top_queries || geebsQ?.top_queries) && <p>Top searches people find us with: {[...(geebsQ?.top_queries || []).slice(0, 2), ...(titanQ?.top_queries || []).slice(0, 1)].map((q) => `“${q.query}”`).join(', ')}.</p>}
          <details className="handoff-daycard__more"><summary>Is this what they always ask, or just now?</summary>
            <div className="handoff-daycard__moreinner">
              <p>This week: {pillarNames[data.trends?.what_people_ask?.current?.top_pillar] || 'unavailable'} ({data.trends?.what_people_ask?.current?.top_share_pct ?? '—'}% of the messages we could sort) · 28 days: {pillarNames[data.trends?.what_people_ask?.window_28d?.top_pillar] || 'unavailable'} ({data.trends?.what_people_ask?.window_28d?.top_share_pct ?? '—'}%) · 90 days: {pillarNames[data.trends?.what_people_ask?.window_90d?.top_pillar] || 'unavailable'} ({data.trends?.what_people_ask?.window_90d?.top_share_pct ?? '—'}%).</p>
            </div>
          </details>
        </article>
      </div>
      {Array.isArray(data.blockers) && data.blockers.length > 0 && <details className="handoff-daycard__more" style={{ marginTop: '1.5rem' }}>
        <summary>What got in the way of these numbers ({Math.min(3, data.blockers.length)})</summary>
        <div className="handoff-daycard__moreinner"><div className="handoff-retro__list">{data.blockers.slice(0, 3).map((b, i) => <div key={b}><b>Problem {i + 1}</b><span>{b}</span></div>)}</div></div>
      </details>}
    </div>
  </section>;
}

function formatScholarshipAnswer(value, labels = null) {
  if (value === null || value === undefined || value === '') return 'Not answered';
  if (typeof value !== 'string' && typeof value !== 'number') return 'Not answered';
  const key = String(value);
  return labels && Object.prototype.hasOwnProperty.call(labels, key) ? String(labels[key]) : key;
}

function CoachingTrackerSection() {
  const [budgetFilter, setBudgetFilter] = useState('all');
  const [budgetRangeFilter, setBudgetRangeFilter] = useState('all');
  const [report, setReport] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [month, setMonth] = useState('all');
  const [completion, setCompletion] = useState('all');
  const [contactFilter, setContactFilter] = useState('all');
  const [contacted, setContacted] = useState({});
  const [contactError, setContactError] = useState('');
  const loadContacts = async () => {
    try {
      const response = await fetch('/api/team/coaching-contacts', { cache: 'no-store' });
      if (!response.ok) return;
      const payload = await response.json();
      const next = {};
      // event_kind is a TOGGLE. Only setting on 'contacted' meant an
      // 'uncontacted' event was ignored, so un-marking someone came back as
      // contacted on the next load. Latest event wins. (Latent on 2026-10-12:
      // the one uncontacted event had no earlier contacted event to survive.)
      for (const event of [...(payload.events || [])].sort(
        (a, b) => String(a.occurred_at).localeCompare(String(b.occurred_at)))) {
        if (event.event_kind === 'contacted') next[event.applicant_id] = event.actor || 'Someone';
        else delete next[event.applicant_id];
      }
      setContacted(next);
    } catch { /* the tracker still works unmarked; never block the list on this */ }
  };
  const toggleContacted = async (applicantId) => {
    // Same identity the weekly checklist already uses, so one "who am I"
    // choice at the top of the page covers every tracker on it.
    const actor = (typeof window !== 'undefined' && window.localStorage.getItem(WEEKLY_HANDOFF_ACTOR_KEY)) || 'Steve';
    const wasContacted = Boolean(contacted[applicantId]);
    const eventKind = wasContacted ? 'uncontacted' : 'contacted';
    setContactError('');
    // Optimistic, then reconciled from the server on failure.
    setContacted((prev) => {
      const next = { ...prev };
      if (wasContacted) delete next[applicantId]; else next[applicantId] = actor;
      return next;
    });
    try {
      const response = await fetch('/api/team/coaching-contacts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ applicantId, actor, eventKind }),
      });
      if (!response.ok) throw new Error('save failed');
    } catch {
      setContactError('That change did not save. Check your connection and try again.');
      void loadContacts();
    }
  };
  const load = async (event) => {
    event?.preventDefault();
    setLoading(true); setError(''); setReport(null);
    void loadContacts();
    try {
      const response = await fetch('/api/team/coaching-report', { cache: 'no-store' });
      if (!response.ok) {
        setError('The coaching report could not be loaded. Try again.');
        return;
      }
      const result = await response.json();
      if (!Array.isArray(result.applications) || !Array.isArray(result.months)) throw new Error('Invalid report');
      setReport(result);
    } catch { setError('The coaching report could not be loaded. Check your connection and try again.'); }
    finally { setLoading(false); }
  };
  useEffect(() => { void load(); }, []);
  const date = (value) => value && Number.isFinite(Date.parse(value)) ? new Date(value).toLocaleString('en-US', { timeZone: 'America/New_York' }) : 'Not recorded';
  // Budget is what the team looks at first, so the list leads with it: highest
  // stated monthly budget first, then newest activity (2026-10-05).
  const budgetFloor = (app) => { const m = String(app.budget_range || '').replace(/,/g, '').match(/(\d+(?:\.\d+)?)\s*(k)?/i); return app.budget_status === 'stated' && m ? Number(m[1]) * (m[2] ? 1000 : 1) : -1; };
  const budgetRanges = [...new Set((report?.applications || []).map((app) => app.budget_range).filter(Boolean))].sort((a, b) => budgetFloor({ budget_status: 'stated', budget_range: b }) - budgetFloor({ budget_status: 'stated', budget_range: a }));
  const visible = report?.applications.filter(app => (month === 'all' || app.months.includes(month))
    && (budgetRangeFilter === 'all' || app.budget_range === budgetRangeFilter)
    && (budgetFilter === 'all' || (budgetFilter === 'no_stated_budget' ? app.budget_status !== 'stated' : app.budget_status === budgetFilter))
    && (completion === 'all' || app.completion === completion)
    && (contactFilter === 'all'
      || (contactFilter === 'contacted' ? Boolean(contacted[app.id]) : !contacted[app.id])))
    .sort((a, b) => budgetFloor(b) - budgetFloor(a) || String(b.latest_at || '').localeCompare(String(a.latest_at || ''))) || [];
  return <section className="section" aria-label="Geebs coaching applications"><div className="wrap">
    <SectionHead eyebrow="Geebs coaching" title="Coaching contacts and applications." intro="View everyone who started a coaching application, including unfinished forms. Open their answers, then use their email or phone number to follow up. Tick Contacted when you have reached someone: it saves for the whole team, not just your device, so Steve and Kris can see what the other has already done." />
    <button type="button" onClick={load} disabled={loading}>{loading ? 'Loading contacts…' : 'Refresh contacts'}</button>
    {error && <p role="alert">{error}</p>}
    {loading && <p role="status">Loading coaching applications…</p>}
    {report && <>
      <p>Updated {date(report.generated_at)}. Dates and months use Eastern time. Month includes anyone who applied during that month; repeat applications appear together. Highest stated monthly budget appears first, then newest activity.</p>
      <details className="handoff-daycard__more">
        <summary>Open the full list ({report.applications.length} contact{report.applications.length === 1 ? '' : 's'})</summary>
        <div className="handoff-daycard__moreinner">
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16 }}>
          <label>Application month <select value={month} onChange={event => setMonth(event.target.value)}><option value="all">All history</option>{report.months.map(value => <option key={value} value={value}>{value}</option>)}</select></label>
          <label>Completion <select value={completion} onChange={event => setCompletion(event.target.value)}><option value="all">All applications</option><option value="submitted">Submitted</option><option value="incomplete">Incomplete</option><option value="unknown">Completion unknown</option></select></label>
          <label>Budget range <select value={budgetRangeFilter} onChange={event => setBudgetRangeFilter(event.target.value)}><option value="all">All ranges</option>{budgetRanges.map((value) => <option key={value} value={value}>{value}</option>)}</select></label>
          <label>Monthly budget <select value={budgetFilter} onChange={event => setBudgetFilter(event.target.value)}><option value="all">Everyone</option><option value="stated">Budget range recorded</option><option value="no_stated_budget">No budget range recorded</option><option value="unanswered">No answer saved</option><option value="not_stated">Answered without a budget range</option></select></label>
          <label>Contact <select value={contactFilter} onChange={event => setContactFilter(event.target.value)}><option value="all">Everyone</option><option value="contacted">Contacted</option><option value="uncontacted">Not contacted yet</option></select></label>
        </div>
        <p>Budget ranges come from earlier applications. Choosing a coaching option does not state income or a dollar budget. Everyone stays in the list when you choose Everyone.</p>
        {contactError && <p role="alert">{contactError}</p>}
        <p role="status">{visible.length} contact{visible.length === 1 ? '' : 's'} shown.</p>
        {!visible.length ? <p>{report.applications.length ? 'No applications match these filters.' : 'No coaching applications found.'}</p> : <div style={{ overflowX: 'auto', marginTop: 24 }}><table className="weekly-scholarship-table"><caption>Geebs coaching application history</caption><thead><tr><th scope="col">Contacted</th><th scope="col">Contact</th><th scope="col">Application dates</th><th scope="col">Completion and readiness</th><th scope="col">Booking and follow-up</th><th scope="col">Answers and source</th></tr></thead><tbody>{visible.map(app => <tr key={app.id}>
          <td><label className="coaching-contacted"><input type="checkbox" checked={Boolean(contacted[app.id])} onChange={() => toggleContacted(app.id)} aria-label={`Mark ${app.name || 'this contact'} contacted`} />{contacted[app.id] ? <span>Marked by {contacted[app.id]}</span> : <span>Not yet</span>}</label></td>
          <td><strong>{app.name || 'Name not provided'}</strong><p>{app.email ? <a href={`mailto:${encodeURIComponent(app.email)}`}>{app.email}</a> : 'Email not provided'}</p><p>{app.phone ? <a href={`tel:${app.phone.replace(/[^+\d]/g, '')}`}>{app.phone}</a> : 'Phone not provided'}</p><p>Instagram: {app.ig_handle || 'Not provided'}</p></td>
          <td>First: {date(app.applied_at)}{app.latest_at !== app.applied_at && <p>Latest: {date(app.latest_at)}</p>}</td>
          <td>{app.completion === 'submitted' ? 'Submitted' : app.completion === 'incomplete' ? 'Incomplete' : 'Completion unknown'}<p>Last saved step: {app.last_saved_step ?? 'Not recorded'}</p><p>Readiness: {app.readiness || 'Not answered'}</p></td>
          <td><p>Booking: {formatScholarshipAnswer(app.booking_status, { booked: 'Booked', unbooked: 'Not booked', canceled: 'Canceled' })}</p>{app.booking_scheduled_at && <p>Scheduled: {date(app.booking_scheduled_at)}</p>}</td>
        
          <td><details><summary>View answers and source</summary><div style={{ minWidth: 240 }}>{app.answers.map(answer => <p key={answer.label}><strong>{answer.label}:</strong> {formatScholarshipAnswer(answer.value)}</p>)}<p><strong>Application page:</strong> {app.source.path || 'Not recorded'}</p><p><strong>Source:</strong> {[app.source.source, app.source.medium, app.source.campaign].filter(Boolean).join(' · ') || 'Not recorded'}</p></div></details></td>
        </tr>)}</tbody></table></div>}
        </div>
      </details>
    </>}
  </div></section>;
}

// 2026-10-12 (Gonzalo): "if we have applicants not marked as contacted those need
// to be surfaced ... show the ones we need to contact, prioritising USA users".
// Both programmes answered the same question in two different folds, so nobody
// could see the whole queue. This is the one list, ahead of both trackers.
//
// WHAT THE DATA CAN AND CANNOT SAY (measured 2026-10-12, live):
//   * Scholarship carries `country` on 20/20 -> "United States" is a VERIFIED fact.
//   * Coaching carries NO country field at all, and only 4/12 phones have any
//     country code (+44, +92, +42, +96 - none +1). So a coaching applicant can
//     never be sorted into "USA"; they go in "country not captured" and are NOT
//     silently ranked below or above the US group on a value we do not have.
//   * Acquisition source exists only for coaching, inside `source.path` as a
//     query string (utm_source on 8/12: site x4, ig x4). It is CHANNEL level -
//     "ig / link_in_bio" - never which post. Scholarship has no source at all.
// Anything unknown says so in words rather than rendering a confident blank.
// 2026-10-13 (Gonzalo): "add the phone numbers so one can easily click them to
// text or WhatsApp". Two different links, and they do NOT have the same
// requirements, which is the whole reason this is a function and not a template:
//   * tel: works on a bare local number - a 10-digit US-shaped number dials fine
//     from Steve's phone. Measured 2026-10-13: 6 of 13 are 10-digit, no country
//     code, and a tel: link is still correct for all of them.
//   * wa.me REQUIRES a country code. Guessing one sends the message to a
//     stranger, so WhatsApp is offered ONLY when the code is known: either the
//     number carries a leading +, or the application states a country whose code
//     we are sure of. 5 of 13 carry a +; 2 more are scholarship rows with a
//     confirmed country. The remaining ones get no WhatsApp button and say why.
const CONTACT_QUEUE_DIAL_CODES = { US: '1', CA: '1' };

function contactQueuePhone(raw, country) {
  const digits = String(raw || '').replace(/[^\d+]/g, '');
  if (!digits) return null;
  const tel = digits.startsWith('+') ? digits : digits.replace(/\D/g, '');
  if (tel.replace(/\D/g, '').length < 7) return null;
  let whatsapp = null;
  if (digits.startsWith('+')) {
    whatsapp = digits.slice(1).replace(/\D/g, '');
  } else {
    const code = CONTACT_QUEUE_DIAL_CODES[country];
    // +1 is a 10-digit national number; anything else and we do not know the
    // shape well enough to prepend a code.
    if (code === '1' && tel.length === 10) whatsapp = code + tel;
  }
  return { display: String(raw).trim(), tel, whatsapp };
}

function contactQueueDaysWaiting(appliedAt) {
  if (!appliedAt) return null;
  const then = new Date(appliedAt);
  if (Number.isNaN(then.getTime())) return null;
  return Math.max(0, Math.floor((Date.now() - then.getTime()) / 86400000));
}

function contactQueueSource(application) {
  const path = (application.source || {}).path || '';
  if (!path) return null;
  try {
    const parseQs = (str) => {
      const map = {};
      for (const pair of (str || '').split('&')) {
        if (!pair) continue;
        const [k, v] = pair.split('=');
        try {
          map[decodeURIComponent(k)] = decodeURIComponent(v || '');
        } catch {}
      }
      return (k) => map[k];
    };
    const query = parseQs(path.split('?')[1] || '');
    const entry = parseQs(
      decodeURIComponent(query('entry_path') || '').split('?')[1] || '');
    const pick = (key) => query(key) || entry(key);
    const source = pick('utm_source');
    const content = pick('utm_content');
    if (!source && !content) return null;
    return [source, content].filter(Boolean).join(' · ').replace(/_/g, ' ');
  } catch {
    return null;
  }
}

// The money signal, in the words a coach reads, for BOTH programmes and for the
// people who never answered. Measured live 2026-10-13: of 14 waiting, the
// scholarship income band was answered on 2 of 3 and the coaching budget on 1
// of 11. A blank cell on the other 11 reads as "no budget", which is a claim
// the data does not make, so the absence is written out loud instead.
const CONTACT_QUEUE_INCOME = {
  'under-2k': 'Under $2,000 a month',
  '2k-5k': '$2,000 to $5,000 a month',
  '5k-10k': '$5,000 to $10,000 a month',
  '10k-20k': '$10,000 to $20,000 a month',
  '20k+': '$20,000 or more a month',
  'prefer-not-say': 'Chose not to say what they take home',
};

function contactQueueMoney(application, programme) {
  if (programme === 'Scholarship') {
    const band = String(application.monthly_take_home_income || '').trim();
    if (!band) return { text: 'Take-home income not answered', answered: false };
    return { text: `Takes home ${CONTACT_QUEUE_INCOME[band] || band}`, answered: true };
  }
  const range = String(application.budget_range || '').trim();
  if (range) return { text: `Budget ${range}`, answered: true };
  return { text: 'Budget not answered', answered: false };
}

function ContactQueueSection() {
  const [rows, setRows] = useState(null);
  const [error, setError] = useState('');

  const load = async () => {
    try {
      const get = async (url) => {
        const response = await fetch(url, { cache: 'no-store' });
        if (!response.ok) throw new Error(url);
        return response.json();
      };
      const [scholarship, coaching, scholarshipEvents, coachingEvents] = await Promise.all([
        get('/api/team/scholarship-report'), get('/api/team/coaching-report'),
        get('/api/team/scholarship-contacts'), get('/api/team/coaching-contacts'),
      ]);
      // Latest event wins. event_kind is a TOGGLE (contacted / uncontacted), so
      // "has a contacted event anywhere" would keep showing someone as done
      // after they were un-marked.
      const settled = (payload) => {
        const state = {};
        for (const event of [...(payload.events || [])].sort(
          (a, b) => String(a.occurred_at).localeCompare(String(b.occurred_at)))) {
          state[event.applicant_id] = event.event_kind;
        }
        return state;
      };
      const scholarshipState = settled(scholarshipEvents);
      const coachingState = settled(coachingEvents);
      const waiting = [];
      for (const application of scholarship.applications || []) {
        if (scholarshipState[application.id] === 'contacted') continue;
        const country = application.country || null;
        waiting.push({
          id: application.id, name: application.name, programme: 'Scholarship',
          appliedAt: application.applied_at, country,
          where: country === 'US' ? [application.city, application.state].filter(Boolean).join(', ') : null,
          came: null, group: country === 'US' ? 0 : 2,
          money: contactQueueMoney(application, 'Scholarship'),
          phone: contactQueuePhone(application.phone, country),
          days: contactQueueDaysWaiting(application.applied_at),
        });
      }
      for (const application of coaching.applications || []) {
        if (coachingState[application.id] === 'contacted') continue;
        waiting.push({
          id: application.id, name: application.name, programme: 'Coaching',
          appliedAt: application.applied_at, country: null, where: null,
          came: contactQueueSource(application), group: 1,
          money: contactQueueMoney(application, 'Coaching'),
          phone: contactQueuePhone(application.phone, null),
          days: contactQueueDaysWaiting(application.applied_at),
        });
      }
      // Newest application first (2026-10-13). Ordered ONLY by when someone
      // applied: 11 of 14 never answered the budget question and the coaching
      // form stores no country, so ranking on money or country would push
      // people down the list on data that was never collected. The waiting
      // badge is what keeps a long wait from sinking out of sight.
      waiting.sort((a, b) => a.group - b.group
        || String(b.appliedAt).localeCompare(String(a.appliedAt)));
      setRows(waiting);
    } catch {
      setError('The contact queue could not load. The two trackers below still work.');
    }
  };
  useEffect(() => { void load(); }, []);

  if (error) return <section className="section"><div className="wrap"><p>{error}</p></div></section>;
  if (!rows) return null;
  const counts = {
    scholarship: rows.filter((r) => r.programme === 'Scholarship').length,
    coaching: rows.filter((r) => r.programme === 'Coaching').length,
    us: rows.filter((r) => r.group === 0).length,
  };
  const GROUPS = [
    [0, 'United States', 'Country confirmed on the application. Contact these first.'],
    [1, 'Country not captured', 'The coaching form never asks for a country, and these phone numbers carry no country code. They are not sorted below the US group on a guess.'],
    [2, 'Outside the United States', 'Country confirmed on the application.'],
  ];
  return <section className="section" aria-label="Who needs contacting"><div className="wrap">
    <SectionHead eyebrow="Contact queue" title="Who needs contacting."
      intro="Everyone from both programmes who has not been marked contacted, newest application first. Each person shows what they said about money, and says so plainly when they never answered. A low income band on a scholarship application is the reason the scholarship exists, not a reason to call someone later. Mark people off in the trackers; this list follows them." />
    <p className="contact-queue__count">
      <strong>{rows.length} waiting</strong> · {counts.scholarship} scholarship · {counts.coaching} coaching · {counts.us} confirmed in the US
    </p>
    {rows.length === 0
      ? <p>Everyone who has applied has been marked contacted.</p>
      : GROUPS.map(([group, title, note]) => {
        const inGroup = rows.filter((r) => r.group === group);
        if (!inGroup.length) return null;
        return <div key={group} className="contact-queue__group">
          <h3 className="contact-queue__group-title">{title} · {inGroup.length}</h3>
          <p className="contact-queue__group-note">{note}</p>
          <ul className="contact-queue__list">{inGroup.map((row) => <li key={row.id} className="contact-queue__row">
            <span className="contact-queue__name">
              {row.name || 'Name not captured'}
              {row.days !== null && row.days >= 14
                ? <span className="contact-queue__stale">waiting {row.days} days</span> : null}
            </span>
            <span className={`contact-queue__money ${row.money && row.money.answered ? '' : 'contact-queue__money--unanswered'}`}>
              {row.money ? row.money.text : 'Nothing recorded about money'}
            </span>
            <span className="contact-queue__meta">
              {row.programme}
              {row.where ? ` · ${row.where}` : ''}
              {row.appliedAt
                ? ` · applied ${String(row.appliedAt).slice(0, 10)}${row.days !== null && row.days < 14 ? ` (${row.days === 0 ? 'today' : `${row.days}d ago`})` : ''}`
                : ''}
            </span>
            {row.phone
              ? <span className="contact-queue__actions">
                <a className="contact-queue__action" href={`tel:${row.phone.tel}`}>Call</a>
                <a className="contact-queue__action" href={`sms:${row.phone.tel}`}>Text</a>
                {row.phone.whatsapp
                  ? <a className="contact-queue__action" href={`https://wa.me/${row.phone.whatsapp}`}
                      target="_blank" rel="noreferrer">WhatsApp</a>
                  : <span className="contact-queue__action contact-queue__action--off"
                      title="WhatsApp needs a country code and this number does not carry one">
                      WhatsApp needs a country code</span>}
                <span className="contact-queue__number">{row.phone.display}</span>
              </span>
              : <span className="contact-queue__came">No phone number on the application</span>}
            <span className="contact-queue__came">
              {row.came ? `Came from: ${row.came}` : 'Where they came from was not captured'}
            </span>
          </li>)}</ul>
        </div>;
      })}
  </div></section>;
}

function ScholarshipTrackerSection() {
  const [report, setReport] = useState(undefined);
  const [error, setError] = useState('');
  // Restored 2026-09-21: the tracker had shipped as a flat table, so Steve and
  // Kris could not narrow the list or record who they had already called.
  const [cityFilter, setCityFilter] = useState('all');
  const [incomeFilter, setIncomeFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [contactFilter, setContactFilter] = useState('all');
  const [contacted, setContacted] = useState({});
  const [contactError, setContactError] = useState('');
  const loadContacts = async () => {
    try {
      const response = await fetch('/api/team/scholarship-contacts', { cache: 'no-store' });
      if (!response.ok) return;
      const payload = await response.json();
      const next = {};
      // event_kind is a TOGGLE. Only setting on 'contacted' meant an
      // 'uncontacted' event was ignored, so un-marking someone came back as
      // contacted on the next load. Latest event wins. (Latent on 2026-10-12:
      // the one uncontacted event had no earlier contacted event to survive.)
      for (const event of [...(payload.events || [])].sort(
        (a, b) => String(a.occurred_at).localeCompare(String(b.occurred_at)))) {
        if (event.event_kind === 'contacted') next[event.applicant_id] = event.actor || 'Someone';
        else delete next[event.applicant_id];
      }
      setContacted(next);
    } catch { /* the tracker still works unmarked; never block the list on this */ }
  };
  const toggleContacted = async (applicantId) => {
    // Same identity the weekly checklist already uses, so one "who am I"
    // choice at the top of the page covers both.
    const actor = (typeof window !== 'undefined' && window.localStorage.getItem(WEEKLY_HANDOFF_ACTOR_KEY)) || 'Steve';
    const wasContacted = Boolean(contacted[applicantId]);
    const eventKind = wasContacted ? 'uncontacted' : 'contacted';
    setContactError('');
    // Optimistic, then reconciled from the server on failure.
    setContacted((prev) => {
      const next = { ...prev };
      if (wasContacted) delete next[applicantId]; else next[applicantId] = actor;
      return next;
    });
    try {
      const response = await fetch('/api/team/scholarship-contacts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ applicantId, actor, eventKind }),
      });
      if (!response.ok) throw new Error('save failed');
    } catch {
      setContactError('That change did not save. Check your connection and try again.');
      void loadContacts();
    }
  };
  const load = async () => {
    setError('');
    void loadContacts();
    try {
      const response = await fetch('/api/team/scholarship-report');
      if (!response.ok) { setError('The scholarship report could not be loaded. Try again.'); setReport(null); return; }
      setReport(await response.json());
    } catch {
      setError('The scholarship report could not be loaded. Check your connection and try again.');
      setReport(null);
    }
  };
  useEffect(() => { load(); }, []);
  // The filter derives its options from live answers, so every stored value
  // needs a label here or the raw slug reaches the page.
  const incomeRank = { '20k+': 6, '10k-20k': 5, '5k-10k': 4, '2k-5k': 3, 'under-2k': 2, 'prefer-not-say': 1 };
  const income = { 'under-2k': 'Under $2,000', '2k-5k': '$2,000–$5,000', '5k-10k': '$5,000–$10,000', '10k-20k': '$10,000–$20,000', '20k+': '$20,000+', 'prefer-not-say': 'Prefer not to say' };
  const commitment = { '0-2days': '0–2 days/week', '3-4days': '3–4 days/week', '5-6days': '5–6 days/week', daily: 'Daily' };
  const experience = { never: 'Never trained seriously', 'less-than-1yr': 'Less than 1 year', '1-2yrs': '1–2 years', '3-5yrs': '3–5 years', '5plus-yrs': '5+ years', 'used-to': 'Took a break' };
  const uniqueSorted = (values) => [...new Set(values.filter((value) => typeof value === 'string' && value.trim()))].sort();
  const cityOptions = uniqueSorted((report?.applications || []).map((app) => app.city));
  const incomeOptions = uniqueSorted((report?.applications || []).map((app) => app.monthly_take_home_income)).sort((a, b) => (incomeRank[b] || 0) - (incomeRank[a] || 0));
  const statusOptions = uniqueSorted((report?.applications || []).map((app) => app.status));
  // Income is the first thing the team checks, so the list is ordered by it:
  // highest take-home income first, unanswered last, newest first within a band.
  const byIncome = (a, b) => (incomeRank[b.monthly_take_home_income] || 0) - (incomeRank[a.monthly_take_home_income] || 0) || String(b.applied_at || '').localeCompare(String(a.applied_at || ''));
  const visible = (report?.applications || []).filter((app) => {
    if (cityFilter !== 'all' && app.city !== cityFilter) return false;
    if (incomeFilter === 'unanswered' ? Boolean(app.monthly_take_home_income?.trim()) : incomeFilter !== 'all' && app.monthly_take_home_income !== incomeFilter) return false;
    if (statusFilter !== 'all' && app.status !== statusFilter) return false;
    if (contactFilter === 'contacted' && !contacted[app.id]) return false;
    if (contactFilter === 'not-contacted' && contacted[app.id]) return false;
    return true;
  }).sort(byIncome);
  const contactedCount = (report?.applications || []).filter((app) => contacted[app.id]).length;
  if (report === undefined) return null;
  if (!report) return <section className="section" aria-label="Scholarship applications"><div className="wrap"><SectionHead eyebrow="Scholarship applications" title="The scholarship report did not load." intro={error || 'Try again to load the latest applications.'} /><Btn kind="ember" type="button" onClick={load}>Try again</Btn></div></section>;
  return <section className="section" aria-label="Scholarship applications"><div className="wrap">
    <SectionHead eyebrow="Scholarship applications" title={`${report.funnel.submitted} submitted; ${report.funnel.stopped_after_contact} stopped after sharing contact details.`} intro={`Current through ${new Date(report.generated_at).toLocaleString()}. ${report.funnel.still_in_progress} application${report.funnel.still_in_progress === 1 ? ' is' : 's are'} still inside the 24-hour completion window.`} />
    <div className="task-detail__cards">
      <article><span>Contact captured</span><b>{report.funnel.contact_captured}</b><p>Distinct people with a saved application contact.</p></article>
      <article><span>Application submitted</span><b>{report.funnel.submitted}</b><p>{report.funnel.completion_rate_pct}% completed the full application.</p></article>
      <article><span>Drop-off after contact</span><b>{report.funnel.stopped_after_contact}</b><p>{report.funnel.dropoff_rate_pct}% stopped for at least 24 hours after sharing contact details.</p></article>
    </div>
    <p style={{ opacity: 0.75 }}>{report.note}</p>
    {/* 2026-10-14: the three numbers above are the answer; the whole list and
        its filters are one tap away rather than a table a coach has to scroll
        past. Nothing is removed from the page -- a closed fold still holds its
        rows, and the contact queue above is the list to work from. */}
    <details className="handoff-daycard__more">
      <summary>Open the full list ({report.applications.length} application{report.applications.length === 1 ? '' : 's'})</summary>
      <div className="handoff-daycard__moreinner">
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16, marginTop: 16 }}>
        <label>City / area <select value={cityFilter} onChange={(event) => setCityFilter(event.target.value)}><option value="all">All cities</option>{cityOptions.map((value) => <option key={value} value={value}>{value}</option>)}</select></label>
        <label>Monthly take-home income <select value={incomeFilter} onChange={(event) => setIncomeFilter(event.target.value)}><option value="all">All incomes</option><option value="unanswered">Not answered</option>{incomeOptions.map((value) => <option key={value} value={value}>{income[value] || value}</option>)}</select></label>
        <label>Status <select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option value="all">All statuses</option>{statusOptions.map((value) => <option key={value} value={value}>{value}</option>)}</select></label>
        <label>Contact <select value={contactFilter} onChange={(event) => setContactFilter(event.target.value)}><option value="all">Everyone</option><option value="contacted">Contacted</option><option value="not-contacted">Not contacted yet</option></select></label>
      </div>
      <p role="status">{visible.length} of {report.applications.length} application{report.applications.length === 1 ? '' : 's'} shown · {contactedCount} marked contacted.</p>
      {contactError && <p role="alert">{contactError}</p>}
      <div style={{ overflowX: 'auto', marginTop: 24 }}><table className="weekly-scholarship-table"><thead><tr><th>Contacted</th><th>Name</th><th>Email</th><th>Phone</th><th>City / area</th><th>State</th><th>Country</th><th>Location source</th><th>Monthly take-home income</th><th>Application answers</th><th>Application date</th><th>Status</th></tr></thead><tbody>{visible.map((app) => <tr key={app.id}><td><label style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}><input type="checkbox" checked={Boolean(contacted[app.id])} onChange={() => toggleContacted(app.id)} aria-label={`Mark ${app.name || 'this applicant'} as contacted`} /><span>{contacted[app.id] ? `Yes \u00b7 ${contacted[app.id]}` : 'No'}</span></label></td><td>{app.name}</td><td><a href={`mailto:${app.email}`}>{app.email}</a></td><td><a href={`tel:${app.phone}`}>{app.phone}</a></td><td>{app.city || 'Unknown'}</td><td>{app.state || 'Unknown'}</td><td>{app.country || 'Unknown'}</td><td>{app.location_source || 'Unknown'}</td><td>{app.monthly_take_home_income ? (income[app.monthly_take_home_income] || app.monthly_take_home_income) : 'Not answered'}</td><td><details><summary>View answers</summary><div style={{ minWidth: 260, paddingTop: 10 }}><p><strong>Goal:</strong> {formatScholarshipAnswer(app.goal)}</p><p><strong>Realistic training days:</strong> {formatScholarshipAnswer(app.commitment, commitment)}</p><p><strong>What gets in the way:</strong> {Array.isArray(app.training_pain_points) && app.training_pain_points.length ? app.training_pain_points.filter((item) => typeof item === 'string').join(' · ') || 'Not answered' : 'Not answered'}</p><p><strong>Age:</strong> {formatScholarshipAnswer(app.age)}</p><p><strong>Training experience:</strong> {formatScholarshipAnswer(app.training_experience, experience)}</p><p><strong>May share story/results:</strong> {app.proof_consents?.testimonial === true ? 'Yes' : app.proof_consents?.testimonial === false ? 'No' : 'Not answered'}</p><p><strong>Join cohort Telegram:</strong> {app.telegram_opt_in === true ? 'Yes' : app.telegram_opt_in === false ? 'No' : 'Not answered'}</p></div></details></td><td>{new Date(app.applied_at).toLocaleString()}</td><td>{app.status}</td></tr>)}</tbody></table></div>
      </div>
    </details>
  </div></section>;
}

function stripEmoji(text) {
  // Competitor bios are scraped verbatim from Instagram and are dense with emoji
  // (flames, arrows, pointing hands). Strip them for display only — the stored
  // data keeps the original string.
  if (typeof text !== 'string') return text;
  return text
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{20E3}]/gu, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

