function PostCaption({ caption, brandName, link, title = 'Caption — paste this into Instagram with the post' }) {
  // Kris and Steve copy this straight into Instagram, so it is shown verbatim
  // and copied verbatim. The link is what feeds the site.
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(caption);
    } catch {
      const scratch = document.createElement('textarea');
      scratch.value = caption;
      document.body.appendChild(scratch);
      scratch.select();
      document.execCommand('copy');
      document.body.removeChild(scratch);
    }
    setCopied(true);
    window.setTimeout(() => setCopied(false), 2000);
  };
  return <div className="post-caption">
    <div className="post-caption__head">
      <strong>{title}</strong>
      {brandName && <span className="post-caption__brand">links to {brandName}</span>}
      <button type="button" className="post-caption__copy" onClick={copy}>{copied ? 'Copied' : 'Copy'}</button>
    </div>
    <pre className="post-caption__text">{caption}</pre>
    {link && <a className="post-caption__link" href={link} target="_blank" rel="noreferrer">Open the linked page</a>}
  </div>;
}

// A link Kris or Steve has to paste somewhere else - the Drive deck folder, a
// post URL, a coach's site - is otherwise a long-press text selection on a
// phone. This copies the exact URL, with the same scratch-textarea fallback the
// caption Copy button uses for older mobile Safari.
function CopyLink({ url, label = 'Copy link' }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(url);
    } catch {
      const scratch = document.createElement('textarea');
      scratch.value = url;
      document.body.appendChild(scratch);
      scratch.select();
      document.execCommand('copy');
      document.body.removeChild(scratch);
    }
    setCopied(true);
    window.setTimeout(() => setCopied(false), 2000);
  };
  if (!url) return null;
  return <button type="button" className="copy-link" onClick={copy}>{copied ? 'Copied' : label}</button>;
}

