function InjuryRehabCoachPage() {
  useReveal();
  const [form, setForm] = useState({ name: '', email: '', primary_lift: '', status: '' });
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    window.titanTrackEvent && window.titanTrackEvent('lead_magnet_submit', { magnet: 'return_protocol', ...form });
    setSubmitted(true);
  };

  return (
    <>
      <Hero
        title="Denver Powerlifting Coach for a Smarter Return to Training"
        subtitle="A tweak does not automatically mean your lifting has to stop. Keep a training rhythm while you work within medical guidance."
        cta="Get the Return Protocol"
        href="#protocol"
      />
      <section className="section section--light section--lg">
        <div className="wrap">
          <SectionHead
            eyebrow="You do not need another generic spreadsheet"
            title="Maintain your training floor."
            intro={<>Many lifters lose momentum after a small setback because their program has no decision rules. <a href="/coaching">TitanForge coaching</a> helps you adjust exercise selection, range of motion, loading, tempo, and weekly volume based on the lifts you care about and the constraints you have right now.</>}
          />
          <div className="grid grid--3">
            <div className="card card--light reveal">
              <h3 className="h4">Keep a productive training floor</h3>
              <p>Protect what can still move forward. Upper body while a lower-body pattern is limited. We keep you showing up.</p>
            </div>
            <div className="card card--light reveal" style={{ transitionDelay: '100ms' }}>
              <h3 className="h4">Progress one variable at a time</h3>
              <p>Load, range of motion, volume, frequency, and exercise variation are levers—not a dare. We advance them deliberately.</p>
            </div>
            <div className="card card--light reveal" style={{ transitionDelay: '200ms' }}>
              <h3 className="h4">Use video feedback</h3>
              <p>Send your top sets. You receive clear coaching cues and programming changes tied to what appears in the lift, not guesswork.</p>
            </div>
          </div>
          <div className="text-center" style={{ marginTop: 48 }}>
            <p className="dim"><em>Important: TitanForge Fit coaches are not medical providers and do not diagnose or treat injuries. Coaching begins after you have the right medical guidance.</em></p>
          </div>
        </div>
      </section>

      <section id="protocol" className="section section--dark section--lg">
        <div className="wrap" style={{ maxWidth: 640 }}>
          <SectionHead
            center
            eyebrow="Free Download"
            title="The Barbell Lifter's Post-Injury Return Protocol"
            intro="Don't default to stopping everything. Get our PDF checklist + 3-day sample modification template to help identify what to clarify with a clinician and how to keep a productive training floor."
          />
          {!submitted ? (
            <form className="form" onSubmit={handleSubmit} style={{ marginTop: 32 }}>
              <div className="form-row">
                <input required type="text" className="input" placeholder="First Name" value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
                <input required type="email" className="input" placeholder="Email Address" value={form.email} onChange={e => setForm({...form, email: e.target.value})} />
              </div>
              <div className="form-row">
                <select required className="input" value={form.primary_lift} onChange={e => setForm({...form, primary_lift: e.target.value})}>
                  <option value="" disabled>Primary Lift Affected</option>
                  <option value="Squat">Squat</option>
                  <option value="Bench">Bench</option>
                  <option value="Deadlift">Deadlift</option>
                  <option value="Other">Other Barbell Pattern</option>
                </select>
              </div>
              <div className="form-row">
                <select required className="input" value={form.status} onChange={e => setForm({...form, status: e.target.value})}>
                  <option value="" disabled>Current Training Status</option>
                  <option value="Cleared">Cleared to train by PT/Doctor</option>
                  <option value="Pending">Pending appointment/clearance</option>
                  <option value="DIY">Working through it myself</option>
                </select>
              </div>
              <Btn kind="primary" block submit arrow>Send me the protocol</Btn>
            </form>
          ) : (
            <div className="card card--light text-center" style={{ marginTop: 32 }}>
              <h3 className="h4 text-ember">Protocol sent!</h3>
              <p>Check your email for the PDF checklist and template.</p>
              <div style={{ marginTop: 24 }}>
                <p><strong>Ready for a customized plan?</strong></p>
                <Btn kind="ember" href="/apply" arrow>Apply for Coaching</Btn>
              </div>
            </div>
          )}
        </div>
      </section>
      <FAQSection route="/powerlifting-coach-[city]-injury-recovery" />
    </>
  );
}

Object.assign(window, { InjuryRehabCoachPage });
